def minDeletionSize(A):
    if not A:
        return 0
    n = len(A[0])
    m = len(A)
    D = set()
    for j in range(n):
        for i in range(m - 1):
            if A[i][j] > A[i+1][j]:
                break
        else:
            for i in range(m):
                if A[i][j] > A[i][j+1]:
                    D.add(j)
                    break
    return len(D)
